/** One post-creation dashboard for library sources and authorized campaign copies. */
public final class CharacterDashboardScreen extends ManagementScreen {
    private final DashboardSource source;
    private DashboardModel.Tab tab=DashboardModel.Tab.OVERVIEW;
    private JsonObject character;
    private JsonObject active=new JsonObject();
    private String campaignName="",campaign="";
    private int spellLevel=-1;

    private CharacterCanvas primary;
    private SectionRail rail;
    private net.minecraft.client.gui.widget.TextFieldWidget filterInput;
    private final Map<DashboardModel.Tab,Integer> panePositions=new EnumMap<>(DashboardModel.Tab.class);
    private DashboardModel.Tab displayed=tab;
    private final Map<DashboardModel.Tab,String> paneFocus=new EnumMap<>(DashboardModel.Tab.class);
    private boolean primaryTab(){return tab==DashboardModel.Tab.OVERVIEW||tab==DashboardModel.Tab.ABILITIES||tab==DashboardModel.Tab.STATISTICS;}
    @Override protected int maximumWidth(){return 980;}
    public CharacterDashboardScreen(Screen parent,DashboardSource source){super("Character Dashboard",parent);this.source=source;}
    public static CharacterDashboardScreen library(Screen parent,String id){return new CharacterDashboardScreen(parent,new DashboardSource(true,id));}
    public static CharacterDashboardScreen campaign(Screen parent,String id){return new CharacterDashboardScreen(parent,new DashboardSource(false,id));}
    @Override protected UiLayout.Rect listBounds(){return CharacterShell.layout(frame).content();}
    @Override protected void searchControls(){filterInput=search(frame.x()+84,frame.y()+frame.height()-30,Math.max(60,frame.width()-182),query,q->{query=q;filter();});button("Refresh","",frame.x()+frame.width()-86,frame.y()+8,74,20,()->{if(!busy)refresh();});}
    @Override protected void controls(){rail=addDrawableChild(new SectionRail(CharacterShell.layout(frame).rail(),Arrays.stream(DashboardModel.Tab.values()).map(t->new SectionRail.Item(t.name(),DashboardModel.title(t))).toList(),v->show(DashboardModel.Tab.valueOf(v))));}
    @Override protected void request(UiApiService.Operation op,JsonObject args,java.util.function.Consumer<UiApiService.Reply> callback){super.request(op,args,r->{if(!r.code().equals("OK")&&!r.code().equals("RATE_LIMIT")){fresh=false;if(r.code().equals("FORBIDDEN")||r.code().equals("NOT_FOUND")||r.code().equals("UNAUTHORIZED")){character=null;if(primary!=null){remove(primary);primary=null;}clearRows();if(list!=null)list.rows(List.of());}}callback.accept(r);});}
    @Override protected void refresh(){if(busy)return;fresh=false;clearRows();if(source.library())read(source.read(),source.readArgs(),data->{character=data;active=new JsonObject();campaign="";campaignName="";display();});else read(ACTIVE,args(),a->{active=a;read(source.read(),source.readArgs(),data->{character=data;campaign=text(data,"campaign");read(CAMPAIGN_GET,args("campaign",campaign),c->{campaignName=text(c,"name");display();});});});}
    private boolean combat(){return flag(active,"inCombat");}
    private boolean selected(){return source.character().equals(text(active,"character"))||source.character().equals(text(active,"boundCharacter"));}
    private boolean editable(){return DashboardModel.editable(character,source.library(),self(),combat());}
    private void display(){if(character==null)return;if(filterInput!=null)filterInput.visible=!primaryTab();clearRows();rail.selected(tab.name());if(primary!=null){panePositions.put(displayed,primary.position());paneFocus.put(displayed,primary.focusedKey());remove(primary);primary=null;}displayed=tab;list.visible=!primaryTab();
        if(primaryTab()){primary=addDrawableChild(new CharacterCanvas(listBounds()));primaryViews();primary.position(panePositions.getOrDefault(tab,0));String key=paneFocus.getOrDefault(tab,"");if(!key.isEmpty()){primary.focus(key);setInitialFocus(primary);}return;}
        switch(tab){case COMBAT->combatTab();case EQUIPMENT->equipment();case FEATURES->features();case SPELLS->spells();case DETAILS->details();case NOTES->notes();case MANAGE->manage();default->{}}filter();}
    private void inspect(FeatureReference.Entry e){client.setScreen(new FeatureInspectScreen(this,e));}
    private void primaryViews(){int x=6,w=primary.getWidth()-12,y=6;
        primary.label(DashboardModel.title(tab),x,y,w,RpgTheme.GOLD);y+=20;
        if(tab==DashboardModel.Tab.ABILITIES){
            var saves=DashboardModel.checks(character,true);var skills=DashboardModel.checks(character,false);
            int columns=w>=540?3:w>=300?2:1,cw=(w-(columns-1)*8)/columns,groupTop=y;
            for(int row=0;row<(6+columns-1)/columns;row++){int bottom=groupTop;for(int col=0;col<columns;col++){int index=row*columns+col;if(index>=6)continue;String key=CreatorDraftState.ABILITIES.get(index);int gx=x+col*(cw+8),gy=groupTop;primary.icon(key,gx,gy,14);primary.label(AbilityWorkspace.NAMES.get(key),gx+18,gy,cw-18,RpgTheme.GOLD);gy+=18;for(var save:saves)if(save.ability().equals(key)){checkEntry(save,"Save",gx,gy,cw);gy+=21;}for(var skill:skills)if(skill.ability().equals(key)){checkEntry(skill,skill.name(),gx,gy,cw);gy+=21;}bottom=Math.max(bottom,gy+8);}groupTop=bottom;}y=groupTop;
            var edit=primary.control("edit:proficiencies",new RpgButton(x,y,w,18,"Edit recorded proficiencies","",()->{if(fresh&&!busy&&editable())client.setScreen(DashboardEditors.proficiencies(this,character,source));}));edit.active=editable();y+=23;
            var scores=primary.control("edit:scores",new RpgButton(x,y,w,18,"Edit saved ability scores","",()->{if(fresh&&!busy&&editable()){if(source.library())client.setScreen(new AbilityScoreScreen(this,character));else client.setScreen(new dev.tacticalcombat.client.ServerCharactersScreen(this,null));}}));scores.active=editable()&&text(character,"profile").equals("srd_5_1");y+=23;
            primary.label("Check/save rolls unavailable: no character-authorized server endpoint.",x,y,w,RpgTheme.MUTED);return;
        }
        if(tab==DashboardModel.Tab.OVERVIEW){
            int cols=primary.getWidth()>=440?6:3,cw=w/cols;
            var scores=DashboardModel.abilities(character);for(int i=0;i<scores.size();i++){var a=scores.get(i);int ax=x+(i%cols)*cw,ay=y+(i/cols)*30;primary.icon(a.label().toLowerCase(Locale.ROOT),ax,ay,12);primary.label(a.label(),ax+15,ay,cw-15,RpgTheme.GOLD);primary.label(a.value().split(" · ")[0],ax,ay+13,cw,RpgTheme.TEXT);}y+=((scores.size()+cols-1)/cols)*30+8;
        }
        var stats=DashboardModel.combat(character,source.library());int statCols=w>=260?2:1,sw=w/statCols;for(int i=0;i<stats.size();i++){var stat=stats.get(i);primary.label(stat.label()+": "+stat.value(),x+i%statCols*sw,y+i/statCols*17,sw-4,RpgTheme.TEXT);}y+=((stats.size()+statCols-1)/statCols)*17+6;
        if(tab==DashboardModel.Tab.STATISTICS){primary.label("Health · library inputs; campaign runtime is read-only",x,y,w,RpgTheme.MUTED);y+=16;for(String key:List.of("hp","temporary_hp")){String name=key.equals("hp")?"HP":"Temporary HP";var minus=primary.control("minus:"+key,new RpgButton(x,y,24,18,"−","",()->health(key,-1)).accessible("Decrease "+name));var plus=primary.control("plus:"+key,new RpgButton(x+28,y,24,18,"+","",()->health(key,1)).accessible("Increase "+name));minus.active=plus.active=source.library()&&editable()&&text(character,"profile").equals("srd_5_1");minus.hint(source.library()?"Save library health with server revision checks":"Campaign edit API does not support combat/health fields");plus.hint(source.library()?"Save library health with server revision checks":"Campaign edit API does not support combat/health fields");primary.label(name,x+58,y+5,w-58,RpgTheme.MUTED);y+=22;}}
        var t=section("trackers");boolean can=trackable();int row=y;
        var inspire=primary.control("inspiration",new RpgButton(x,row,w,18,flag(t,"inspiration")?"Inspiration: Yes":"Inspiration: No","",()->manual(new RpgRecords.Change(RpgRecords.Action.INSPIRATION,"trackers","",0,flag(t,"inspiration")?0:1))));inspire.active=can;y+=24;
        for(boolean successes:List.of(true,false)){String key=successes?"deathSuccesses":"deathFailures";var action=successes?RpgRecords.Action.DEATH_SUCCESSES:RpgRecords.Action.DEATH_FAILURES;int value=t.get(key).getAsInt();primary.label(successes?"Death successes":"Death failures",x,y,w,RpgTheme.MUTED);y+=13;for(int i=1;i<=3;i++){int target=i;var pip=primary.control(key+i,new RpgButton(x+(i-1)*24,y,20,18,i<=value?"●":"○","",()->manual(new RpgRecords.Change(action,"trackers","",0,target==value?target-1:target))).accessible((successes?"Success ":"Failure ")+i));pip.active=can;}y+=24;}
        primary.label("Death saves and inspiration are manual bookkeeping.",x,y,w,RpgTheme.MUTED);y+=20;
        var xp=DashboardModel.xp(character.getAsJsonObject("sheet"));primary.label(xp.label(),x,y,w,RpgTheme.TEXT);y+=15;if(xp.mode().equals("XP")){primary.progress(x,y,w,xp.fraction());y+=10;}y+=5;
        if(tab==DashboardModel.Tab.STATISTICS){for(String key:List.of("species","characterClass","subclass","background","alignment")){primary.label(label(key)+": "+text(section("identity"),key),x,y,w,RpgTheme.TEXT);y+=14;}try{var data=SrdAuthoring.data(character.getAsJsonObject("sheet"));for(String key:List.of("armor_proficiencies","weapon_proficiencies","resistances","immunities","vulnerabilities")){primary.label(label(key)+": "+join(data,key),x,y,w,RpgTheme.MUTED);y+=14;}}catch(RuntimeException ignored){}
            for(var condition:section("features").getAsJsonArray("entries")){var entry=condition.getAsJsonObject();if(text(entry,"kind").equals("CONDITION")){CreatorWorkspace.feature(primary,FeatureReference.recorded(entry),x,y,w,this::inspect);y+=21;}}
            primary.label("Exhaustion: "+t.get("exhaustion").getAsInt(),x,y,w,RpgTheme.TEXT);y+=18;
            for(String sec:List.of("trackers","features"))for(var item:section(sec).getAsJsonArray("resources")){var r=item.getAsJsonObject();String id=text(r,"id");int value=r.get("current").getAsInt(),max=r.get("maximum").getAsInt();primary.label(text(r,"name")+": "+value+" / "+max,x,y,w,RpgTheme.GOLD);y+=13;for(int delta:List.of(-1,1)){var b=primary.control(sec+id+delta,new RpgButton(x+(delta<0?0:28),y,24,18,delta<0?"−":"+","",()->manual(new RpgRecords.Change(RpgRecords.Action.RESOURCE,sec,id,0,Math.clamp(value+delta,0,max)))));b.active=trackable(sec)&&text(r,"status").equals("MANUAL");}y+=24;}
        }else{
            try{var data=SrdAuthoring.data(character.getAsJsonObject("sheet"));for(String key:List.of("resistances","immunities","vulnerabilities")){primary.label(label(key)+": "+join(data,key),x,y,w,RpgTheme.MUTED);y+=14;}}catch(RuntimeException ignored){}
            for(boolean conditions:List.of(true,false)){primary.label(conditions?"Conditions · recorded":"Notable Features · recorded",x,y,w,RpgTheme.GOLD);y+=18;var records=section("features").getAsJsonArray("entries").asList().stream().map(JsonElement::getAsJsonObject).filter(e->text(e,"kind").equals("CONDITION")==conditions).toList();if(records.isEmpty()){primary.label("None recorded",x,y,w,RpgTheme.MUTED);y+=16;}for(var entry:records.stream().limit(3).toList()){CreatorWorkspace.feature(primary,FeatureReference.recorded(entry),x,y,w,this::inspect);y+=21;}if(records.size()>3){primary.label("More records in Features & Feats",x,y,w,RpgTheme.MUTED);y+=16;}}
            String clazz=text(section("identity"),"characterClass");var match=Srd2014Catalog.CLASSES.stream().filter(c->c.name().equals(clazz)).findFirst();if(match.isPresent()){primary.label("Class reference · not granted automatically",x,y,w,RpgTheme.MUTED);y+=18;for(var entry:FeatureReference.classFeatures(match.get().id()).stream().filter(e->e.level()<=xp.level()).limit(3).toList()){CreatorWorkspace.feature(primary,entry,x,y,w,this::inspect);y+=21;}}
        }

    }
    private void checkEntry(DashboardModel.Check check,String label,int x,int y,int width){var e=new FeatureReference.Entry("sheet:check:"+label+":"+check.name(),label.equals("Save")?check.name()+" saving throw":check.name(),"Saved character · manual tabletop projection",0,"","Manual/non-executable","","","",check.breakdown(),"INFORMATIONAL",check.breakdown()+" No authorized check/save dice endpoint exists. P = recorded proficiency; E = recorded expertise.");primary.control(e.id(),new RpgButton(x,y,width,18,(label.equals("Save")?"Save":label)+"  "+check.display(),"",()->inspect(e)).hint(e.tooltip()));}
    private void health(String key,int delta){if(busy||!fresh||!source.library()||!editable())return;try{var data=SrdAuthoring.data(character.getAsJsonObject("sheet"));int current=data.get(key).getAsInt(),max=key.equals("hp")?data.get("hp_max").getAsInt():Integer.MAX_VALUE;data.addProperty(key,(int)Math.clamp((long)current+delta,0L,(long)max));mutate(source.edit(),source.sectionArgs(character,"combat",data),next->{character=next;display();});}catch(RuntimeException invalid){message=invalid.getMessage();}}
    private void combatTab(){for(var stat:DashboardModel.combat(character,source.library()))info(stat.label(),stat.value()+" · "+stat.authority());JsonObject data=null;try{data=SrdAuthoring.data(character.getAsJsonObject("sheet"));}catch(RuntimeException ignored){}if(data!=null){info("Automated weapons",join(data,"weapons")+" · existing Phase 3 server attack authority");info("Armor",text(data,"armor")+(flag(data,"shield")?" + shield":"")+" · existing SRD codec");}info("Actions","Existing Phase 3 attack/movement controls are available through encounter controls.");info("Bonus actions / reactions","No separate automated catalog; inspect manually recorded features below.");JsonObject trackers=section("trackers");trackerRows(trackers);JsonObject features=section("features");for(var e:features.getAsJsonArray("entries")){var f=e.getAsJsonObject();if(text(f,"kind").equals("CONDITION"))info("Condition: "+text(f,"name"),text(f,"source")+" · "+text(f,"status")+" · not necessarily enforced");}row("Open encounter controls","Use existing verified combat actions; this dashboard creates no outcomes",!source.library(),source.library()?"Library sources are not active combatants":"",()->client.setScreen(new DestinationScreen(this,DestinationScreen.Destination.ENCOUNTERS)));}
    private void trackerRows(JsonObject t){boolean edit=trackable();chooseTracker("Death-save successes",RpgRecords.Action.DEATH_SUCCESSES,t.get("deathSuccesses").getAsInt(),3,edit);chooseTracker("Death-save failures",RpgRecords.Action.DEATH_FAILURES,t.get("deathFailures").getAsInt(),3,edit);chooseTracker("Exhaustion",RpgRecords.Action.EXHAUSTION,t.get("exhaustion").getAsInt(),6,edit);int i=0;for(var e:t.getAsJsonArray("hitDice")){var h=e.getAsJsonObject();valueTracker("Hit Dice d"+h.get("sides").getAsInt(),RpgRecords.Action.HIT_DICE,"trackers","",i++,h.get("current").getAsInt(),h.get("maximum").getAsInt(),edit);}for(var e:t.getAsJsonArray("resources")){var p=e.getAsJsonObject();valueTracker(text(p,"name"),RpgRecords.Action.RESOURCE,"trackers",text(p,"id"),0,p.get("current").getAsInt(),p.get("maximum").getAsInt(),edit&&text(p,"status").equals("MANUAL"));}}
    private void equipment(){JsonObject inv=section("inventory");var items=new ArrayList<JsonObject>();for(var e:inv.getAsJsonArray("items"))items.add(e.getAsJsonObject());items.sort(Comparator.<JsonObject,Boolean>comparing(o->!flag(o,"equipped")).thenComparing(o->text(o,"name")));for(var item:items)row(text(item,"name"),item.get("quantity").getAsInt()+" · "+(flag(item,"equipped")?"equipped":"carried")+" · slot "+text(item,"slot")+" · sheet record only",true,"",()->{if(editable())client.setScreen(new WizardRecordsScreen(this,character,"inventory",source));else client.setScreen(new InfoScreen(this,text(item,"name"),"Read-only sheet inventory",item.toString()));});info("Currency",inv.get("platinum").getAsLong()+" pp · "+inv.get("gold").getAsLong()+" gp · "+inv.get("electrum").getAsLong()+" ep · "+inv.get("silver").getAsLong()+" sp · "+inv.get("copper").getAsLong()+" cp");row("Manage sheet inventory","Search, inspect, add, edit or remove manual records. No Minecraft item or combat equipment changes.",editable(),restriction(),()->client.setScreen(new WizardRecordsScreen(this,character,"inventory",source)));}
    private void features(){JsonObject f=section("features");var entries=new ArrayList<JsonObject>();for(var e:f.getAsJsonArray("entries"))entries.add(e.getAsJsonObject());entries.sort(Comparator.comparing(o->text(o,"kind")+text(o,"source")+text(o,"name")));for(var e:entries){String uses=e.has("uses")&&!e.get("uses").isJsonNull()?" · usage pool recorded":"";row(text(e,"name"),text(e,"kind")+" · "+text(e,"source")+" · "+text(e,"status")+uses+" · "+shorten(text(e,"description")),true,"",()->{if(editable())client.setScreen(new WizardRecordsScreen(this,character,"features",source));else client.setScreen(new InfoScreen(this,text(e,"name"),"Read-only feature · no automation implied",e.toString()));});}for(var e:f.getAsJsonArray("resources")){var p=e.getAsJsonObject();valueTracker(text(p,"name"),RpgRecords.Action.RESOURCE,"features",text(p,"id"),0,p.get("current").getAsInt(),p.get("maximum").getAsInt(),trackable("features")&&text(p,"status").equals("MANUAL"));}row("Manage features / feats","Manual and informational records; no mechanics are granted",editable(),restriction(),()->client.setScreen(new WizardRecordsScreen(this,character,"features",source)));}
    private void spells(){JsonObject b=section("spellbook");info("Spellcasting summary",text(b,"recordedAbility")+" · save DC "+text(b,"recordedSaveDc")+" · attack "+text(b,"recordedAttackModifier")+" · recorded/manual");row("Level filter",spellLevel<0?"All spell levels":spellLevel==0?"Cantrips":"Level "+spellLevel,true,"",()->client.setScreen(new ChoiceScreen(this,"Spell level filter",java.util.stream.IntStream.rangeClosed(-1,9).mapToObj(Integer::toString).toList(),v->Integer.parseInt(v)<0?"All":Integer.parseInt(v)==0?"Cantrips":"Level "+v,v->{spellLevel=Integer.parseInt(v);display();})));var selections=new ArrayList<JsonObject>();for(var e:b.getAsJsonArray("selections"))selections.add(e.getAsJsonObject());selections.sort(Comparator.<JsonObject>comparingInt(s->{var d=definition(b,text(s,"spell"));return d==null?99:d.get("level").getAsInt();}).thenComparing(s->{var d=definition(b,text(s,"spell"));return d==null?text(s,"spell"):text(d,"name");}));for(var s:selections){var d=definition(b,text(s,"spell"));if(d!=null&&spellLevel>=0&&d.get("level").getAsInt()!=spellLevel)continue;String name=d==null?text(s,"spell"):text(d,"name");String detail=d==null?"Definition unavailable":((d.get("level").getAsInt()==0?"Cantrip":"Level "+d.get("level").getAsInt())+" · "+text(d,"school")+" · "+(flag(s,"alwaysPrepared")?"always prepared":flag(s,"prepared")?"prepared":flag(s,"known")?"known":"recorded")+" · "+text(d,"castingTime")+" · "+text(d,"range"));row(name,detail,true,"",()->{if(editable())client.setScreen(new WizardRecordsScreen(this,character,"spellbook",source));else client.setScreen(new InfoScreen(this,name,"Read-only custom spell · no Cast action",d==null?s.toString():d.toString()));});}int i=0;for(var e:b.getAsJsonArray("slots")){var s=e.getAsJsonObject();valueTracker("Level "+s.get("level").getAsInt()+" spell slots",RpgRecords.Action.SPELL_SLOT,"spellbook","",i++,s.get("current").getAsInt(),s.get("maximum").getAsInt(),trackable("spellbook"));}info("Standard catalog","Empty and explicitly unavailable; custom definitions only. No Cast Spell action exists.");row("Manage custom spellbook","Search/filter custom records and preparation flags",editable(),restriction(),()->client.setScreen(new WizardRecordsScreen(this,character,"spellbook",source)));}
    private void details(){JsonObject identity=section("identity"),progression=section("progression");for(String key:List.of("species","characterClass","subclass","background","alignment","age","height","appearance"))info(label(key),text(identity,key).isBlank()?"Not recorded":text(identity,key));var xp=DashboardModel.xp(character.getAsJsonObject("sheet"));info("Progression",xp.label());row("Edit identity and details","Canonical fields; campaign saves may invalidate approval under policy",editable(),restriction(),()->client.setScreen(DashboardEditors.identity(this,character,source)));row("Edit recorded progression","Informational only; does not level combat statistics",editable(),restriction(),()->client.setScreen(DashboardEditors.progression(this,character,source)));}
    private void notes(){JsonObject i=section("identity");for(String key:List.of("biography","personality","ideals","bonds","flaws"))info(label(key),text(i,key).isBlank()?"Not recorded":shorten(text(i,key)));row("Edit bounded narrative notes","No separate unlimited notes field exists; unsaved form text is retained",editable(),restriction(),()->client.setScreen(DashboardEditors.notes(this,character,source)));}
    private void manage(){if(source.library()){info("Personal library source",text(character,"stage")+" · independent template");row("Open lifecycle and submission management","Validate, finalize, duplicate and submit independent copies",true,"",()->client.setScreen(new LibraryCharacterScreen(this,source.character())));for(var e:array(character,"submissions")){var c=e.getAsJsonObject();row(text(c,"campaignName"),flag(c,"approved")?"Campaign copy approved":"Campaign copy awaiting approval",true,"",()->client.setScreen(CharacterDashboardScreen.campaign(this,text(c,"id"))));}}else{info("Campaign",campaignName+" · "+(flag(character,"approved")?"approved":"awaiting approval")+" · "+(text(character,"bound").isEmpty()?"unbound":"bound"));info("Ownership / control","Owner: "+player(character,text(character,"owner"))+" · controller: "+player(character,text(character,"controller")));row("Approve Character","Approve supported fields; approval does not bind",canApprove(character,true),"DM authority and unbound character required",()->reviewApproval(true));row("Request Changes / Revoke","Revoke approval; no written review conversation is implied",canApprove(character,false),"DM authority and unbound character required",()->reviewApproval(false));row("Assign Player Control","Offer control to a campaign member; ownership stays unchanged",canManageCharacter(character),"DM authority and unbound character required",()->client.setScreen(new PlayerPickerScreen(this,campaign,true,p->{var assignment=character.has("assignment")&&character.get("assignment").isJsonObject()?character.getAsJsonObject("assignment"):null;long ar=assignment==null?0:revision(assignment);long expected=revision(character);confirm("Offer character control?",text(character,"name")+" → "+text(p,"name")+". The player must accept; this never binds the character.",()->mutate(ASSIGNMENT_OFFER,args("character",source.character(),"revision",expected,"assignmentRevision",ar,"player",text(p,"id")),d->refresh()));})));
        row("Bind Character","Choose an eligible loaded entity; server rechecks approval/control",canManageCharacter(character)&&flag(character,"approved"),"DM authority, approval and unbound character required",()->client.setScreen(new BindingPickerScreen(this,source.character(),entity->{long expected=revision(character);confirm("Bind character?",text(character,"name")+" → "+text(entity,"name")+". Selection and assignment are distinct from binding.",()->mutate(BIND,args("character",source.character(),"revision",expected,"entity",text(entity,"id")),d->refresh()));})));
        row("Open campaign character management","Approval, assignment, binding and source navigation",true,"",()->client.setScreen(new CampaignCharacterScreen(this,source.character())));row("Rest requests","Request Short/Long Rest or review existing state; recovery remains manual",true,"",()->client.setScreen(new RestScreen(this,campaign)));row("Recent activity","Bounded session history, permission-filtered by server",true,"",()->client.setScreen(new RecentActivityScreen(this,campaign)));}}
    private void reviewApproval(boolean approve){long expected=revision(character);confirm(approve?"Approve Character?":"Request Changes / Revoke?",approve?"Approve this supported server revision. Full build legality still requires DM review. Approval does not bind.":"Revoke approval and mark changes required. Existing backend has no written review thread.",()->mutate(approve?CHARACTER_APPROVE:CHARACTER_REVOKE,args("character",source.character(),"revision",expected),d->refresh()));}
    private void show(DashboardModel.Tab next){tab=next;display();}
    private JsonObject section(String key){return SheetSections.read(character.getAsJsonObject("sheet"),key);}
    private String restriction(){return DashboardModel.restriction(character,source.library(),self(),combat());}
    private boolean trackable(){return trackable("trackers");}
    private boolean trackable(String section){return source.library()?editable():flag(character,"canTrack")&&character.has("manualRevision")&&array(character,"manualSections").asList().stream().anyMatch(e->e.getAsString().equals(section));}
    private String trackerRestriction(){return "Requires current control or DM authority and campaign permission for this manual section";}
    private void manual(RpgRecords.Change change){if(!trackable(change.section())){message=trackerRestriction();return;}mutate(source.manualOperation(),source.manualArgs(character,change),data->{character=data;display();});}
    private void chooseTracker(String name,RpgRecords.Action action,int value,int max,boolean enabled){row(name,Integer.toString(value)+" · manual tracker",enabled,trackerRestriction(),()->client.setScreen(new ChoiceScreen(this,name,java.util.stream.IntStream.rangeClosed(0,max).mapToObj(Integer::toString).toList(),v->v,v->manual(new RpgRecords.Change(action,"trackers","",0,Integer.parseInt(v))))));}
    private void valueTracker(String name,RpgRecords.Action action,String section,String key,int index,int value,int max,boolean enabled){row(name,value+" / "+max+" · manual resource",enabled,trackerRestriction(),()->{var field=List.of(new RecordFormScreen.Field("value","Current (0–"+max+")",Integer.toString(value),5));client.setScreen(new RecordFormScreen(this,name,source.read(),source.readArgs(),field,(state,v)->source.manualArgs(state,new RpgRecords.Change(action,section,key,index,WizardEditors.integer(v,"value",0,max))),source.manualOperation(),data->client.setScreen(this),"Server-confirmed inert bookkeeping; does not heal, recover resources automatically, or change combat.").expected(character));});}
    private static String join(JsonObject o,String key){var v=new ArrayList<String>();for(var e:array(o,key))v.add(e.getAsString());return v.isEmpty()?"None":String.join(", ",v);}
    private static JsonObject definition(JsonObject b,String id){for(var e:b.getAsJsonArray("customDefinitions")){var d=e.getAsJsonObject();if(text(d,"id").equals(id))return d;}return null;}
    private static String label(String key){return switch(key){case "characterClass"->"Class";default->Character.toUpperCase(key.charAt(0))+key.substring(1);};}
    private static String shorten(String value){return value.length()>140?value.substring(0,137)+"…":value;}
    @Override protected void content(DrawContext g,int mx,int my,float delta){if(character==null)return;var s=CharacterShell.layout(frame).summary();RpgTheme.panel(g,s.x(),s.y(),s.width(),s.height(),RpgTheme.PANEL,false);String identity=text(character,"name")+"\nLevel "+DashboardModel.xp(character.getAsJsonObject("sheet")).level()+"\n"+DashboardModel.header(character,source.library(),selected(),combat())+"\n"+DashboardModel.xp(character.getAsJsonObject("sheet")).label();if(CharacterShell.layout(frame).compactSummary())RpgTheme.text(g,textRenderer,text(character,"name")+" · L"+DashboardModel.xp(character.getAsJsonObject("sheet")).level()+" · "+text(section("identity"),"species")+" · "+text(section("identity"),"characterClass"),s.x()+5,s.y()+(s.height()-9)/2,s.width()-10,RpgTheme.GOLD);else{if(client.player!=null&&(source.library()||text(character,"owner").equals(self())))PlayerSkinDrawer.draw(g,client.player.getSkinTextures(),s.x()+s.width()/2-12,s.y()+8,24);paragraphs(g,identity,s.x()+6,s.y()+38,s.width()-12,s.height()-44);}}

    @Override protected int statusWidth(){return Math.max(40,frame.width()-320);}
}
